#include <cstddef>

void bubble_sort(int* a, size_t n) {
    if (n < 2) return;
    for (size_t i = 0; i + 1 < n; ++i) {
        bool swapped = false;
        for (size_t j = 0; j + 1 < n - i; ++j) {
            if (a[j] > a[j + 1]) {
                int tmp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = tmp;
                swapped = true;
            }
        }
        if (!swapped) break;
    }
}

namespace {

void merge(int* a, size_t lo, size_t mid, size_t hi) {
    size_t n1 = mid - lo;
    size_t n2 = hi - mid;
    int* left = new int[n1];
    int* right = new int[n2];
    for (size_t i = 0; i < n1; ++i) left[i] = a[lo + i];
    for (size_t i = 0; i < n2; ++i) right[i] = a[mid + i];

    size_t i = 0, j = 0, k = lo;
    while (i < n1 && j < n2) {
        if (left[i] <= right[j]) a[k++] = left[i++];
        else a[k++] = right[j++];
    }
    while (i < n1) a[k++] = left[i++];
    while (j < n2) a[k++] = right[j++];

    delete[] left;
    delete[] right;
}

void merge_sort_rec(int* a, size_t lo, size_t hi) {
    if (hi - lo < 2) return;
    size_t mid = lo + (hi - lo) / 2;
    merge_sort_rec(a, lo, mid);
    merge_sort_rec(a, mid, hi);
    merge(a, lo, mid, hi);
}

} // namespace

void merge_sort(int* a, size_t n) {
    if (n < 2) return;
    merge_sort_rec(a, 0, n);
}
