  int total = 0;
  for (auto& item : in.items)
    total += processItem(item);
  save_state(total);
  return total;
}

int processItem(const Item& item) {
  if (!item.valid) return 0;
  int contribution = item.value + bonusFor(item);
  applyPolicy(item);
  return contribution;
}

int bonusFor(const Item& item) {
  return (item.value >= 0 && item.value <= 100) ? 2 : 0;
}

void applyPolicy(const Item& item) {
  if (item.value > 100)      { log_warning(item.id); retry(item); }
  else if (item.value < 0)   { log_error(item.id);   skip(item);  }
}
```

